from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent;scenes=json.loads((R/'scenes.json').read_text())
style='''*{box-sizing:border-box}body{margin:0;background:#faf8f4;color:#293229;font:15px/1.6 system-ui,sans-serif}header,main{max-width:1500px;margin:auto;padding:28px}h1{font:48px Georgia;margin:8px 0 15px}h2{font:30px Georgia}p{max-width:850px}a{color:#3f5e51;text-underline-offset:4px}nav{display:flex;gap:12px;flex-wrap:wrap}nav a,button,select{border:1px solid #74816c;padding:10px 15px;border-radius:6px;background:#fff;color:#293229;font:inherit}section{border-top:1px solid #c9cec5;padding:24px 0 36px}.views{display:grid;grid-template-columns:1.5fr 1fr .7fr;gap:22px;align-items:start}.views figure{margin:0;min-width:0}.views img{width:100%;display:block;border:1px solid #c9cec5;border-radius:5px}.views figcaption{margin:10px 0;font-size:13px}.scene-title{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.scene-title h2{margin:0}.tag{font-size:12px;letter-spacing:1px;color:#596754}iframe{background:#fff;border:1px solid #74816c;display:block;margin:25px auto;max-width:100%}.prototype{overflow:auto}.prototype iframe{max-width:none}@media(max-width:750px){h1{font-size:36px}header,main{padding:22px}.views{grid-template-columns:1fr}.views figure{max-width:650px}.views figure:last-child{max-width:390px}}'''
body='''<header><div class="tag">AURA / DEWDROP · DESIGN VERSION 1 · MILESTONE 1</div><h1>A little care. A daily ritual.</h1><p>15 connected scenes. 45 independently rendered PNGs. 15 additional boards. Fictional products and accounts; visual references for LetBuyy’s canonical commerce, identity and checkout.</p><nav><a href="Dewdrop-45-mockups.zip">Download 45 PNGs</a><a href="prototype-index.html">Responsive source</a><a href="comparisons/side-by-side.html">Shopify comparisons</a><a href="comparisons/neutral-structure.html">Neutral structure</a><a href="README.md">Handoff & dependencies</a><a href="validation.json">Validation</a></nav></header><main><nav>'''
body+=''.join(f'<a href="#{s["id"]}">{s["id"][:2]} {html.escape(s["title"])}</a>' for s in scenes)+'</nav>'
for s in scenes:
 body+=f'<section id="{s["id"]}"><div class="scene-title"><h2>{s["id"][:2]} / {html.escape(s["title"])}</h2><a href="boards/{s["id"]}.png">Three-device board</a></div><p>{html.escape(s["description"])}</p><div class="views">'
 for d,w,h in [('desktop',1440,1000),('tablet',834,1112),('mobile',390,844)]:body+=f'<figure><figcaption>{d.title()} / {w} × {h} CSS px / DPR 1 · <a href="images/{s["id"]}-{d}.png">Full PNG</a></figcaption><a href="images/{s["id"]}-{d}.png"><img loading="lazy" src="images/{s["id"]}-{d}.png" alt="Dewdrop {html.escape(s["title"])} {d}"></a></figure>'
 body+='</div></section>'
body+='</main>'
(R/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dewdrop responsive storybook</title><style>'+style+'</style>'+body+'</html>')
opts=''.join(f'<option value="{s["source"]}">{s["id"]} · {html.escape(s["title"])}</option>' for s in scenes)
(R/'prototype-index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dewdrop editable source</title><style>'''+style+'''</style><header><a href="index.html">← Storybook</a><h1>Dewdrop presentation source</h1><p>Static visual prototype. Shade, menu and quantity demos run locally; no API, account, payment or order changes occur. These scenes are connected views of one home/PDP/account journey.</p><nav><select id="scene" aria-label="Scene">'''+opts+'''</select><button data-width="1440" data-height="1000">Desktop 1440</button><button data-width="834" data-height="1112">Tablet 834</button><button data-width="390" data-height="844">Mobile 390</button><a id="direct" href="source/01-home-top.html">Open source directly</a></nav></header><main class="prototype"><iframe id="frame" title="Dewdrop responsive scene" src="source/01-home-top.html" width="1440" height="1000"></iframe></main><script>let f=document.querySelector('#frame');document.querySelector('#scene').onchange=e=>{f.src=e.target.value;document.querySelector('#direct').href=e.target.value};document.querySelectorAll('button[data-width]').forEach(b=>b.onclick=()=>{f.width=b.dataset.width;f.height=b.dataset.height})</script></html>''')
print('Gallery and source index built')
